CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(100) PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (id TINYINT PRIMARY KEY, data JSON NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content (
 id VARCHAR(64) PRIMARY KEY, collection VARCHAR(32) NOT NULL, slug VARCHAR(160) NOT NULL, title VARCHAR(180) NOT NULL,
 data JSON NOT NULL, published BOOLEAN NOT NULL DEFAULT FALSE, sort_order INT NOT NULL DEFAULT 0,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY content_slug (collection,slug), KEY published_order (collection,published,sort_order)
);
CREATE TABLE IF NOT EXISTS admins (id VARCHAR(64) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(300) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY,admin_id VARCHAR(64) NOT NULL,expires_at DATETIME NOT NULL, FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE,KEY session_expiry(expires_at));
CREATE TABLE IF NOT EXISTS rate_limits (bucket CHAR(64) PRIMARY KEY,attempts INT NOT NULL,reset_at DATETIME NOT NULL,KEY rate_expiry(reset_at));
CREATE TABLE IF NOT EXISTS enquiries (
 id VARCHAR(64) PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(254) NOT NULL,subject VARCHAR(180) NOT NULL,message TEXT NOT NULL,
 status ENUM('new','read','resolved') NOT NULL DEFAULT 'new',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY enquiry_status(status,created_at)
);
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY,admin_id VARCHAR(64) NOT NULL,action VARCHAR(80) NOT NULL,target VARCHAR(180) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
